#!/usr/bin/env node
/**
 * Applies pending Prisma migrations using the `pg` driver.
 *
 * `prisma migrate deploy` is unavailable in EngLoop's engine-free setup (see
 * docs/adr/0001-engine-free-prisma.md): it introspects the database through the
 * driver adapter, which cannot yet decode PostgreSQL's internal `name` type.
 * The migration *files* are still generated by Prisma — this script only reads
 * them, applies each one in a transaction and records it in `_prisma_migrations`
 * exactly as Prisma does, so `prisma migrate status` stays authoritative.
 *
 *   node scripts/deploy-migrations.mjs              apply pending migrations
 *   node scripts/deploy-migrations.mjs --baseline   record them as applied
 *                                                   WITHOUT running the SQL
 *
 * `--baseline` is the equivalent of `prisma migrate resolve --applied`: use it
 * when the schema already exists (an earlier `db push`, a restored dump, an
 * established production database) and only the migration history needs to
 * catch up. It never touches your data.
 */
import { createHash, randomUUID } from 'node:crypto';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { config as readEnvFile } from 'dotenv';
import pg from 'pg';

const here = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.join(here, '..');
for (const file of [path.join(packageRoot, '..', '..', '.env'), path.join(packageRoot, '.env')]) {
  if (existsSync(file)) readEnvFile({ path: file, override: false, quiet: true });
}

const connectionString = process.env.DATABASE_URL;
if (!connectionString) {
  console.error('DATABASE_URL is not set. Copy .env.example to .env first.');
  process.exit(1);
}

const baseline = process.argv.includes('--baseline');

const migrationsDir = path.join(packageRoot, 'prisma', 'migrations');
if (!existsSync(migrationsDir)) {
  console.error(`No migrations directory at ${migrationsDir}`);
  process.exit(1);
}

const migrations = readdirSync(migrationsDir, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)
  .sort()
  .map((name) => ({
    name,
    file: path.join(migrationsDir, name, 'migration.sql'),
  }))
  .filter((migration) => existsSync(migration.file));

const client = new pg.Client({ connectionString });
await client.connect();

try {
  await client.query(`
    CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
      id                  VARCHAR(36) PRIMARY KEY NOT NULL,
      checksum            VARCHAR(64) NOT NULL,
      finished_at         TIMESTAMPTZ,
      migration_name      VARCHAR(255) NOT NULL,
      logs                TEXT,
      rolled_back_at      TIMESTAMPTZ,
      started_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
      applied_steps_count INTEGER NOT NULL DEFAULT 0
    )`);

  const { rows } = await client.query('SELECT migration_name FROM "_prisma_migrations"');
  const applied = new Set(rows.map((row) => row.migration_name));
  const pending = migrations.filter((migration) => !applied.has(migration.name));

  if (pending.length === 0) {
    console.error(`No pending migrations (${String(migrations.length)} already applied).`);
    process.exit(0);
  }

  for (const migration of pending) {
    const sql = readFileSync(migration.file, 'utf8');
    const checksum = createHash('sha256').update(sql).digest('hex');
    const startedAt = new Date();

    // One transaction per migration: a failure leaves no half-applied schema
    // and no row claiming it succeeded.
    await client.query('BEGIN');
    try {
      if (!baseline) await client.query(sql);
      await client.query(
        `INSERT INTO "_prisma_migrations"
           (id, checksum, finished_at, migration_name, started_at, applied_steps_count)
         VALUES ($1, $2, now(), $3, $4, $5)`,
        [randomUUID(), checksum, migration.name, startedAt, baseline ? 0 : 1],
      );
      await client.query('COMMIT');
      console.error(`${baseline ? 'baselined' : 'applied  '} ${migration.name}`);
    } catch (error) {
      await client.query('ROLLBACK');
      const message = error instanceof Error ? error.message : String(error);
      console.error(`failed    ${migration.name}: ${message}`);
      if (/already exists/i.test(message)) {
        console.error(
          [
            '',
            'The schema is already in the database but the migration history is empty.',
            'Record the history without re-running the SQL:',
            '  pnpm db:baseline',
            'or, on a development database you can safely wipe:',
            '  pnpm db:reset && pnpm db:seed',
          ].join('\n'),
        );
      }
      process.exitCode = 1;
      break;
    }
  }
} finally {
  await client.end();
}
